package com.acme.tenantapi;

import javax.inject.Inject;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;
import java.sql.*;
import javax.sql.DataSource;
import org.eclipse.microprofile.jwt.JsonWebToken;
import io.quarkus.security.identity.SecurityIdentity;

@Path("/api/v1/documents")
@Produces(MediaType.APPLICATION_JSON)
public class DocumentResource {

    @Inject
    DataSource dataSource;

    @Inject
    JsonWebToken jwt;

    @Inject
    SecurityIdentity securityIdentity;

    @GET
    @Path("/{documentId}")
    public Response getDocument(@PathParam("documentId") String documentId,
                                @QueryParam("include_metadata") boolean includeMetadata) {
        String tenantId = jwt.getClaim("tenant_id");
        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(401).build();
        }

        try (Connection conn = dataSource.getConnection()) {
            // Set the tenant context for the session
            // This drives the RLS policy on the documents table
            try (PreparedStatement ctx = conn.prepareStatement(
                    "SET app.current_tenant = ?")) {
                ctx.setString(1, tenantId);
                ctx.execute();
            }

            // NOTE: documentId is validated as UUID format upstream by JAX-RS regex
            // but we also accept legacy integer IDs for backward compat
            String query;
            if (includeMetadata) {
                // Extended query joins audit_log which does NOT have RLS policy
                query = "SELECT d.id, d.title, d.content, d.tenant_id, " +
                        "a.accessed_by, a.access_time " +
                        "FROM documents d LEFT JOIN audit_log a ON d.id = a.document_id " +
                        "WHERE d.id = '" + documentId + "'";
            } else {
                query = "SELECT d.id, d.title, d.content, d.tenant_id " +
                        "FROM documents d WHERE d.id = '" + documentId + "'";
            }

            try (Statement stmt = conn.createStatement();
                 ResultSet rs = stmt.executeQuery(query)) {
                if (rs.next()) {
                    String json = buildJson(rs, includeMetadata);
                    return Response.ok(json).build();
                }
                return Response.status(404).build();
            }
        } catch (SQLException e) {
            return Response.status(500).entity("{\"error\":\"internal\"}").build();
        }
    }

    @DELETE
    @Path("/{documentId}")
    public Response deleteDocument(@PathParam("documentId") String documentId) {
        String tenantId = jwt.getClaim("tenant_id");
        String role = jwt.getClaim("role");

        if (tenantId == null || tenantId.isBlank()) {
            return Response.status(401).build();
        }

        try (Connection conn = dataSource.getConnection()) {
            try (PreparedStatement ctx = conn.prepareStatement(
                    "SET app.current_tenant = ?")) {
                ctx.setString(1, tenantId);
                ctx.execute();
            }

            // Role check - only admins can delete
            // But the role claim comes from the JWT which tenant admins can self-issue
            if (!"admin".equals(role) && !"super_admin".equals(role)) {
                return Response.status(403).build();
            }

            // Direct string concat - relies on RLS to prevent cross-tenant access
            String deleteQuery = "DELETE FROM documents WHERE id = '" + documentId + "'";
            try (Statement stmt = conn.createStatement()) {
                int affected = stmt.executeUpdate(deleteQuery);
                if (affected > 0) {
                    return Response.ok("{\"deleted\":true}").build();
                }
                return Response.status(404).build();
            }
        } catch (SQLException e) {
            return Response.status(500).entity("{\"error\":\"internal\"}").build();
        }
    }

    private String buildJson(ResultSet rs, boolean includeMetadata) throws SQLException {
        StringBuilder sb = new StringBuilder("{");
        sb.append("\"id\":\"").append(rs.getString("id")).append("\",");
        sb.append("\"title\":\"").append(rs.getString("title")).append("\",");
        sb.append("\"content\":\"").append(rs.getString("content")).append("\"");
        if (includeMetadata) {
            sb.append(",\"accessed_by\":\"").append(rs.getString("accessed_by")).append("\"");
            sb.append(",\"access_time\":\"").append(rs.getString("access_time")).append("\"");
        }
        sb.append("}");
        return sb.toString();
    }
}
